NAME = 'NlCanisius1939: Petrus Canisius Translation'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: 'Paulus, apostel van Christus Jesus, volgens de beschikking van God, onzen Zaligmaker, en van Christus Jesus, onze hoop:',
        2: 'aan Timóteus, zijn rechtgeaard kind in het geloof: genade, barmhartigheid en vrede van God den Vader en van Jesus Christus onzen Heer.',
        3: 'Zoals ik u bij mijn vertrek naar Macedonië ver. zocht heb, moet ge in Éfese blijven, om sommige lieden te verbieden, vreemde dingen te leren,',
        4: 'en zich bezig te houden met fabels en eindeloze geslachtslijsten, die zich beter lenen voor twistvragen dan voor de geloofsbedeling Gods.',
        5: 'Immers het doel der prediking is liefde, die voortspruit uit een rein hart, een goed geweten en een ongeveinsd geloof.',
        6: 'Dit hebben die lieden uit het oog verloren, en daardoor zijn ze in leeg gepraat vervallen;',
        7: 'ze willen leraars zijn der Wet, maar begrijpen niet eens wat ze zeggen, en wat ze zo stellig beweren.',
        8: 'Zeker we weten, dat de Wet goed is, zo men haar toepast op wettige wijze;',
        9: 'en zo men bedenkt, dat de Wet niet gemaakt is voor den rechtvaardige, maar voor tuchtelozen en losbandigen, voor goddelozen en zondaars, voor heiligschenners en ongodsdienstigen, voor vadermoorders en moedermoorders, voor doodslagers,',
        10: 'ontuchtigen en knapenschenners, voor mensenrovers, leugenaars en meinedigen, -en wat er verder in strijd is met de gezonde leer,',
        11: 'volgens het Evangelie der glorie van den gelukzaligen God, dat aan mij is toevertrouwd.',
        12: 'Dank breng ik Hem, die mij sterkte, Christus Jesus onzen Heer, omdat Hij mij trouw heeft geacht en in bediening heeft gesteld,',
        13: 'hoewel ik toch vroeger een godslasteraar was, een vervolger en geweldenaar. Maar omdat ik het in ongeloof onwetend deed, vond ik ontferming;',
        14: 'en overvloedig zelfs stroomde de genade onzes Heren mij toe, met geloof en liefde in Christus Jesus.',
        15: 'Waarachtig is het woord, en volkomen geloofwaardig, dat Christus Jesus in de wereld is gekomen, om zondaars te redden. Ik ben de grootste onder hen;',
        16: 'maar daarom juist heb ik ontferming gevonden, opdat aan mij, den grootste, Jesus Christus zijn volle lankmoedigheid zou tonen, als voorbeeld voor hen, die in Hem zullen geloven ten eeuwigen leven.',
        17: 'Aan den Koning der eeuwen, den onvergankelijken, onzichtbaren, enigen God: eer en glorie in de eeuwen der eeuwen. Amen!',
        18: 'Timóteus, mijn kind, deze prediking vertrouw ik u toe krachtens de profetieën, die vroeger over u zijn uitgebracht. Moogt ge, daarop steunend, de goede strijd blijven strijden,',
        19: 'in het bezit van het geloof en van een goed geweten. Sommigen hebben dit van zich afgestoten, en daardoor schipbreuk geleden in het geloof.',
        20: 'Hiertoe behoren Humeneus en Alexander; ik heb ze Satan overgeleverd, om ze het lasteren af te leren.',
    },
    2: {
        1: 'Vóór alles dus dring ik er op aan, dat er gebeden, smekingen, voorbeden en dankzeggingen worden opgedragen voor alle mensen;',
        2: 'voor koningen ook en alle overheden, opdat we een stil en rustig leven mogen leiden in alle vroomheid en eerbaarheid.',
        3: 'Dit immers is goed en welgevallig aan God onzen Zaligmaker,',
        4: 'die wil, dat àlle mensen zalig worden en tot de kennis der waarheid geraken.',
        5: 'Want er is één God, en ook één Middelaar tussen God en de mensen, de Mens Jesus Christus,',
        6: 'die zich gaf als losprijs voor àllen. Zo luidt de getuigenis voor onze tijd;',
        7: 'hiertoe ben ik aangesteld als heraut en apostel, -ik spreek waarheid, geen leugen, -als leraar der heidenen in geloof en in waarheid.',
        8: 'Ik verlang dus, dat de mannen bidden overal, en reine handen opheffen zonder toorn en twijfel.',
        9: 'Eveneens moeten dan de vrouwen, eerbaar en ingetogen, zich tooien met passende kleding; niet met haarvlechten, goud, paarlen of kostbare kleren,',
        10: 'maar met goede werken, zoals het vrouwen betaamt, die aanspraak maken op godsdienstigheid.',
        11: 'Een vrouw moet onderricht ontvangen, zwijgend en in alle nederigheid.',
        12: 'Ik sta niet toe, dat de vrouw onderricht geeft of meestert over den man; ze moet zich stil houden.',
        13: 'Want Adam werd het eerst geschapen, daarna Eva.',
        14: 'Ook werd Adam niet misleid, maar de vrouw werd bedrogen en kwam ten val.',
        15: 'Toch zal ze zalig worden door het baren van kinderen, zo ze volhardt in geloof, liefde en heiligheid, aan ingetogenheid gepaard.',
    },
    3: {
        1: 'Dit woord is waarachtig! Streeft iemand naar het bisschopsambt, dan begeert hij een voortreffelijke taak.',
        2: 'De bisschop dan moet onberispelijk zijn, slechts éénmaal gehuwd; gematigd, bezonnen, zedig, gastvrij, geschikt voor het onderricht;',
        3: 'geen drinker, geen vechter, maar zachtzinnig, vredelievend, onbaatzuchtig.',
        4: 'Iemand, die zijn eigen huis goed bestiert, en zijn kinderen onder tucht heeft met behoud zijner waardigheid;',
        5: 'zo iemand toch zijn eigen huis niet weet te besturen, hoe zal hij zorg kunnen dragen voor Gods Kerk?',
        6: 'Hij mag geen pasbekeerde zijn, opdat hij niet door trots beneveld in het vonnis van den duivel valt.',
        7: 'Ook te goeder faam moet hij bekend zijn bij hen, die buiten staan, opdat hij niet in schande valt en in de strik van den duivel.',
        8: 'Ook diakens moeten eerbaar zijn; geen dubbele tong, niet verslaafd aan de wijn, op schandelijk gewin niet bedacht;',
        9: 'in een rein geweten moeten ze ronddragen het geheim des geloofs.',
        10: 'Ook zij moeten eerst worden waardig gekeurd, en slechts wanneer ze onberispelijk zijn, als diaken worden aangesteld.',
        11: 'Ook hun vrouwen moeten eerbaar zijn, geen lastertongen; maar gematigd en betrouwbaar in alles.',
        12: 'Diakens mogen slechts éénmaal gehuwd zijn, en moeten hun kinderen en gezinnen goed besturen.',
        13: 'Zij, die het ambt van diaken goed hebben bekleed, verwerven zich een ereplaats en groot aanzien door het geloof in Christus Jesus.',
        14: 'Dit alles schrijf ik u, ofschoon ik hoop, spoedig bij u te komen;',
        15: 'opdat, mocht ik vertraging hebben, ge toch weten zoudt, hoe ge u gedragen moet in het huis van God, de Kerk van den levenden God, zuil en grondslag der waarheid.',
        16: 'Groot is het geheim van de godsdienst, zoals het eensgezind wordt beleden: Hij verscheen in het Vlees, Werd gerechtvaardigd door den Geest; Hij werd door de Engelen aanschouwd, Onder de heidenen gepreekt; Hij werd in de wereld gelovig aanvaard, En opgenomen in de heerlijkheid.',
    },
    4: {
        1: 'Toch zegt de Geest uitdrukkelijk, dat in de laatste tijden sommigen zullen afvallen van het geloof, en aan dwaalgeesten en duivelse leringen gehoor zullen geven,',
        2: 'door de huichelarij van leugenaars, die hun eigen geweten hebben toegeschroeid.',
        3: 'Lieden, die verbieden te trouwen, en spijzen te gebruiken, welke God heeft geschapen, om met dankzegging te worden genuttigd door hen, die geloven en de waarheid hebben erkend.',
        4: 'Inderdaad, al wat door God is geschapen, is goed; en niets is verwerpelijk, zo het onder dankzegging genuttigd wordt;',
        5: 'want dan wordt het geheiligd door Gods woord en gebed.',
        6: 'Zo ge de broeders dit alles voorhoudt, zult ge een goed dienaar zijn van Christus Jesus, u voedend met de woorden van het geloof en met de degelijke leer, die ge u tot richtsnoer gesteld hebt.',
        7: 'Wijs dus de profane oudewijven-fabels van u af. Oefen ook uzelf in godsvrucht.',
        8: 'Want de lichaamsoefening is van weinig nut; maar de godsvrucht is nuttig onder alle opzichten, daar ze de belofte bezit van dit leven en van het toekomstige.',
        9: 'Dit is een waarachtig woord en volkomen geloofwaardig.',
        10: 'Want daarom zwoegen we en strijden we, omdat we onze hoop hebben gevestigd op den levenden God, die de Zaligmaker is van alle mensen, van de gelovigen vooral.',
        11: 'Dit moet ge inscherpen en leren.',
        12: 'Zeker, niemand mag uw jeugd verachten; maar wees gij dan ook een voorbeeld voor de gelovigen in woord en in wandel, in liefde, in geloof en in onschuld.',
        13: 'Schenk uw aandacht aan de voorlezing, opwekking en lering, totdat ik kom.',
        14: 'Wees niet zorgeloos met de genadegave, die ge bezit, en die u krachtens een profetie onder handoplegging der priesterschaar is geschonken.',
        15: 'Draag dáárvoor zorg, en leef er in, opdat uw vooruitgang aan iedereen mag blijken.',
        16: 'Geef acht op uzelf en op het onderricht; blijf daarin volharden. Want zo ge het doet, redt ge uzelf en uw hoorders.',
    },
    5: {
        1: 'Ge moet niet hard optreden tegen een bejaard man, maar hem vermanen als een vader; jongelieden als broeders,',
        2: 'bejaarde vrouwen als moeders, jonge vrouwen als zusters in alle eerbaarheid.',
        3: 'De weduwen moet ge eren, zo ze inderdaad als weduwen alleen staan.',
        4: 'Want zo een weduwe kinderen of kleinkinderen heeft, dan moeten die vóór alles leren, hun eigen familie in ere te houden, en hun ouders het goede te vergelden; want dit is aangenaam aan God.',
        5: 'Wie werkelijk weduwe is en helemaal alleen staat, moet haar hoop op God gevestigd houden, en volharden in bidden en smeken, nacht en dag;',
        6: 'als ze een dartel leven leidt, is ze levend dood.',
        7: 'Ook dit moet ge inscherpen, opdat ze zich onberispelijk gedragen.',
        8: 'En zo er een is, die zich niet om haar familie en heel in het bijzonder zich niet om haar huisgenoten bekommert, dan verloochent ze het geloof, en is erger dan een ongelovige..',
        9: 'Als weduwe mag op de lijst worden geplaatst, die niet beneden de zestig jaren is, en slechts éénmaal gehuwd is geweest.',
        10: 'Ze moet gunstig bekend staan om haar goede werken: dat ze namelijk haar kinderen heeft opgevoed, gastvrijheid beoefend, de voeten der heiligen gewassen, de noodlijdenden ondersteund, en zich aan allerlei goede werken heeft toegewijd.',
        11: 'Maar jonge weduwen moet ge afwijzen. Want wanneer oplaaiende zinnelijkheid haar van Christus vervreemdt, willen ze trouwen;',
        12: 'en ze lopen een veroordeling in, omdat ze de vroegere gelofte hebben verbroken.',
        13: 'Tegelijkertijd leren ze dan leeglopers worden door het houden van huisbezoek; en niet alleen leeglopers, maar ook babbelaars, bemoeiallen, beuzelend over al wat niet past.',
        14: 'Ik verlang dus, dat jongere weduwen trouwen, kinderen ter wereld brengen, haar huishouding besturen, en dat ze den tegenstander geen enkele aanleiding geven tot lasteren.',
        15: 'Feitelijk zijn enkelen reeds achter Satan verloren gelopen.',
        16: 'Wanneer een gelovige vrouw onder haar verwanten weduwen telt, dan moet zij ze bijstaan; men moet de gemeente er niet mee belasten, opdat deze de eigenlijke weduwen kan helpen.',
        17: 'De priesters, die op waardige wijze aan het hoofd staan, moeten dubbele eer worden waardig geacht; vooral als ze zich inspannen door prediking en onderricht.',
        18: 'De Schrift immers zegt: “Een dorsenden os zult ge niet muilbanden,” en “de werkman is zijn loon waard.”',
        19: 'Tegen een priester moogt ge geen aanklacht aanvaarden, dan onder twee of drie getuigen.',
        20: 'Hebben ze gezondigd, straf ze dan in tegenwoordigheid van allen, opdat ook de overigen worden afgeschrikt.',
        21: 'Ik bezweer u bij God en Christus Jesus en bij de uitverkoren Engelen, dat ge dergelijke zaken zonder vooroordeel behandelt, en niets uit partijdigheid doet.',
        22: 'Leg niemand overijld de handen op, en maak u niet schuldig aan vreemde zonden.',
        23: 'Bewaar uw reinheid; drink niet langer water alleen, maar gebruik wat wijn voor uw maag en uw voortdurende ongesteldheid.',
        24: 'Van sommige mensen zijn de zonden reeds vóór de rechterlijke uitspraak bekend, van anderen eerst daarna.',
        25: 'Op dezelfde wijze raken ook de goede werken bekend; in ieder geval, verborgen blijven kunnen ze niet.',
    },
    6: {
        1: 'Allen, die het slavenjuk torsen, moeten hun meesters hoogachten, opdat de naam van God en de leer niet worden gelasterd.',
        2: 'Zij die gelovigen tot meesters hebben, mogen ze niet minachten, omdat ze broeders zijn; maar ze moeten hen des te beter dienen, juist omdat ze gelovigen zijn en welbeminden, die zich toeleggen op weldoen. Zó moet ge leren en vermanen.',
        3: 'Wie vreemde dingen leert, en zich niet houdt aan de gezonde prediking van onzen Heer Jesus Christus en aan de vrome leer,',
        4: 'is door hoogmoed beneveld. Hij begrijpt niets, maar hij is ziek van twistvragen en woordenstrijd, waaruit nijd ontstaat, twist, gelaster, boze argwaan',
        5: 'en voortdurend gewrijf van mensen, die geestelijk bedorven zijn en van de waarheid beroofd, en die menen, dat de godsvrucht hetzelfde is als een bron van verdiensten.',
        6: 'Zeker, de godsvrucht is een krachtige bron van verdiensten, zo ze gepaard gaat met tevredenheid.',
        7: 'We hebben niets in de wereld meegebracht, omdat we er toch ook niets kunnen uitdragen.',
        8: 'Hebben we dus voedsel en kleding, dan moeten we daarmee ook tevreden zijn.',
        9: 'Zij, die echter rijk willen worden, vallen in bekoring en strik, en in vele dwaze en schandelijke begeerten, welke de mensen neerstorten in ondergang en verderf.',
        10: 'Want de wortel van alle kwaad is de geldzucht. Door hieraan toe te geven, zijn sommigen afgedwaald van het geloof, en hebben zich veel stekende pijnen bereid.',
        11: 'Man Gods, gij moet u daarvoor wachten! Streef liever naar gerechtigheid, godsvrucht, geloof, liefde, geduld en zachtmoedigheid.',
        12: 'Strijd de goede strijd van het geloof; ding naar het eeuwige leven, waartoe ge geroepen zijt, en voor vele getuigen de heerlijke belijdenis hebt afgelegd.',
        13: 'Ik beveel u bij God, die alles ten leven verwekt, en bij Christus Jesus, die onder Póntius Pilatus de heerlijke belijdenis heeft afgelegd,',
        14: 'dat ge dit gebod zult volbrengen, vlekkeloos en onberispelijk tot aan de komst van Jesus Christus onzen Heer.',
        15: 'Hem zal te zijner tijd de zalige en enige Heerser openbaren, de Koning der koningen en Heer der heren,',
        16: 'Hij die alleen de onsterfelijkheid bezit, die het ontoegankelijk licht bewoont, dien geen mens heeft gezien of kàn zien, wien de eer is en eeuwige macht. Amen!',
        17: 'Vermaan de rijken dezer wereld, dat ze niet trots mogen zijn; dat ze hun hoop niet stellen op wisselvallige rijkdom, maar op God, die ons rijkelijk van alles voorziet, om er van te genieten;',
        18: 'dat ze deugdzaam moeten zijn en rijk in goede werken, vrijgevig ook en mededeelzaam.',
        19: 'Dan stapelen ze zich voor de toekomst een goede grondslag op, waarop ze het eeuwig leven bereiken.',
        20: 'Timóteus, bewaar het toevertrouwde pand. Wend u af van de profane beuzelpraat, van de twistvragen der zogenaamde Kennis,',
        21: 'waartoe sommigen zich hebben bekend, en het spoor in het geloof zijn bijster geworden. De genade zij met u allen!',
    },
}
